    '[%1$s] Charge complete (Charge ID: %2$s)' => '[%1$s] Ladevorgang abgeschlossen (Lade ID: %2$s)',
    '[%1$s] Could not disbursed fund to vendor. Error From gateway: %2$s' => '[%1$s] Es konnte kein Geld an den Anbieter ausgezahlt werden. Fehler vom Gateway: %2$s',
    '[%1$s] Could not do the Payout of amount %2$s to user: %3$s. Payout settings or verification of the user is incomplete.' => '[%1$s] Auszahlung des Betrags %2$s an Benutzer: %3$s konnte nicht durchgeführt werden. Die Auszahlungseinstellungen oder die Verifizierung des Benutzers sind unvollständig.',
    '[%1$s] Could not do the Payout to user: %2$s. No active bank account found for the user.' => '[%1$s] Auszahlung an Benutzer: %2$s konnte nicht durchgeführt werden. Es wurde kein aktives Bankkonto für den Benutzer gefunden.',
    '[%1$s] Could not reversed %2$s from vendor stripe account. Error: %3$s' => '[%1$s] %2$s konnte nicht vom Stripe Account des Anbieter storniert werden. Fehler: %3$s',
    '[%1$s] Error: Automatic refund is not possible for this order. Reason: No MangoPay transaction id is found. Refund id: %2$s, Order ID: %3$s' => '[%1$s] Fehler: Automatische Erstattung ist für diese Bestellung nicht möglich. Grund: Es wurde keine MangoPay Transaktion ID gefunden. Rückerstattung ID: %2$s, Bestell ID: %3$s',
    '[%1$s] Gateway processing fee: %2$s' => '[%1$s] Gateway Bearbeitungsgebühr: %2$s',
    '[%1$s] Hook note: %2$s' => '[%1$s] Hook Notiz: %2$s',
