    '[%1$s] The opened review for this order is now closed. Reason: %2$s' => '[%1$s] Die eröffnete Überprüfung für diese Bestellung ist jetzt geschlossen. Grund: %2$s',
    '[%1$s] This charge was partially captured via Stripe Dashboard in the amount of: %2$s' => '[%1$s] Diese Gebühr wurde teilweise über Stripe Dashboard in Höhe von erfasst: %2$s',
