    'Check this box if the booking can be cancelled by the customer after it has been purchased. A refund will not be sent automatically.' => 'Aktivieren Sie dieses Kontrollkästchen, wenn die Buchung vom Kunden nach dem Kauf storniert werden kann. Eine Rückerstattung wird nicht automatisch gesendet.',
    'Check this box if the booking requires YOUR approval/confirmation. Payment will not be taken during CHECKOUT.' => 'Aktivieren Sie dieses Kontrollkästchen, wenn für die Buchung IHRE Genehmigung/Bestätigung erforderlich ist. Die Zahlung erfolgt nicht während der KASSE.',
    'Check this box if the coupon grants free shipping. A free shipping method must be enabled in your shipping zone and be set to require "a valid free shipping coupon".' => 'Aktivieren Sie dieses Kontrollkästchen, wenn der Gutschein kostenlosen Versand gewährt. In Ihrer Versandzone muss eine kostenlose Versandmethode aktiviert sein und die "ein gültiger Gutschein für kostenlosen Versand" Einstellung erforderlich sein.',
    'Check this box if the coupon should not apply to items on sale.' => 'Aktivieren Sie dieses Kontrollkästchen, wenn der Gutschein nicht für verkaufte Artikel gelten soll.',
    'Check this box if you want to apply this coupon for all vendors.' => 'Markieren Sie dieses Kästchen, wenn Sie diesen Gutschein für alle Anbieter anwenden möchten.',
    'Check this box if you want to automatically apply this coupon for new products.' => 'Aktivieren Sie dieses Kästchen, wenn Sie diesen Gutschein automatisch auf neue Produkte anwenden möchten.',
    'Check this box if you want to notify selected vendors.' => 'Markieren Sie dieses Feld, wenn Sie ausgewählte Anbieter benachrichtigen möchten.',
    'Check this box if you want to show the coupons on vendors store page.' => 'Markieren Sie dieses Kästchen, wenn Sie die Gutscheine auf der Store Seite des Anbieter anzeigen möchten.',
    'Check this box if you want to show this coupon in store page.' => 'Aktivieren Sie dieses Kontrollkästchen, wenn Sie diesen Gutschein auf der Store Seite anzeigen möchten.',
    'Check this if you want to apply this rule on all products.' => 'Aktivieren Sie diese Option, wenn Sie diese Regel auf alle Produkte anwenden möchten.',
    'Check this if you want to enable shipping for your store' => 'Aktivieren Sie diese Option, wenn Sie den Versand für Ihren Store aktivieren möchten',
    'Check this if you want user to verify their email address upon registration.' => 'Aktivieren Sie diese Option, wenn Sie möchten, dass der Benutzer seine E-Mail Adresse bei der Registrierung verifiziert.',
    'Check this to allow social login/signup for customers and vendors.' => 'Aktivieren Sie dieses Kontrollkästchen, um Kunden und Anbietern die Möglichkeit zu geben, sich über Social Netzwerke anzumelden bzw. zu registrieren.',
    'Check this to allow vendors to override & customize the delivery settings. Otherwise, admin configured settings will be applied.' => 'Aktivieren Sie dieses Kontrollkästchen, um den Anbietern zu erlauben, die Zustellungseinstellungen außer Kraft zu setzen und anzupassen. Andernfalls werden die vom Administrator konfigurierten Einstellungen übernommen.',
    'Check to add Request Quote support for your products.' => 'Aktivieren Sie diese Option, um Support für Angebotsanfrage für Ihre Produkte hinzuzufügen.',
    'Check to disable the shipping method if the rule matches.' => 'Aktivieren Sie diese Option, um die Versandmethode zu deaktivieren, wenn die Regel zutrifft.',
