    'Enter -1 for no advertisement expiration.' => 'Geben Sie -1 ein, wenn die Anzeige nicht ablaufen soll.',
    'Enter a cost (excl. tax) or sum, e.g. <code>10.00 * [qty]</code>. Use <code>[qty]</code> for the number of items, <code>[cost]</code> for the total cost of items, and <code>[fee percent=\'10\' min_fee=\'20\' max_fee=\'\']</code> for percentage based fees.' => 'Geben Sie Kosten (ohne Steuern) oder einen Betrag ein, z.B. <code>10.00 * [qty]</code>. Verwenden Sie <code>[qty]</code> für die Anzahl der Artikel, <code>[cost]</code> für die Gesamtkosten der Artikel und <code>[fee percent=\'10\' min_fee=\'20\' max_fee=\'\']</code> für prozentuale Gebühren.',
    'Enter a cost for this rule. Applied to each booking block.' => 'Geben Sie die Kosten für diese Regel ein. Wird auf jeden Buchungsblock angewendet.',
