    'IDs on action to perform' => 'IDs für auszuführende Aktionen',
    'If a customer buys more than one type product from your store, first product of the every second type will be charged with this price' => 'Wenn ein Kunde mehr als ein Produkt in Ihrem Store kauft, wird das erste Produkt jedes zweiten Typs mit diesem Preis berechnet',
    'If activated, Sellers will pay the Stripe processing fee instead of Admin/Site Owner in 3DS mode.' => 'Wenn aktiviert, zahlen Verkäufer die Stripe Bearbeitungsgebühr anstelle von Admin/Seitenbetreiber im 3DS Modus.',
    'If activated, Sellers will pay the Stripe processing fee instead of Admin/Site Owner.' => 'Wenn aktiviert, zahlen die Verkäufer die Stripe Bearbeitungsgebühr anstelle des Administrators/Seiten Eigentümers.',
    'If both options are enabled, customers will see both Printful and marketplace shipping methods at checkout.' => 'Wenn beide Optionen aktiviert sind, werden den Kunden beim Bezahlvorgang sowohl die Versandmethoden von Printful als auch die des Marktplatzes angezeigt.',
    'If checked, non-connected sellers will receive announcement notice to connect their MangoPay account. ' => 'Wenn diese Option aktiviert ist, erhalten nicht verbundene Verkäufer eine Ankündigung, ihr MangoPay Account zu verbinden. ',
    'If checked, non-connected sellers will receive announcement notice to connect their PayPal account. ' => 'Wenn diese Option aktiviert ist, erhalten nicht verbundene Verkäufer eine Ankündigung, ihren PayPal Account zu verbinden. ',
    'If checked, non-connected sellers will receive announcement notice to connect their Razorpay account. ' => 'Wenn diese Option aktiviert ist, erhalten nicht verbundene Verkäufer eine Ankündigung, ihr RazorPay Account zu verbinden. ',
    'If checked, non-connected sellers will receive announcement notice to connect their Stripe account once in a week.' => 'Wenn diese Option aktiviert ist, erhalten nicht verbundene Anbieter einmal in der Woche eine Benachrichtigung, dass sie ihren Stripe Account verbinden sollen.',
    'If checked, non-connected sellers will receive announcement notice to connect their Stripe account. ' => 'Wenn diese Option aktiviert ist, erhalten nicht verbundene Anbieter eine Ankündigung, ihren Stripe Account zu verbinden. ',
    'If checked, non-connected sellers will receive announcement notice to sign up for a Stripe Express account. ' => 'Wenn diese Option aktiviert ist, erhalten nicht verbundene Verkäufer eine Ankündigung, sich für ein Stripe Express Account anzumelden. ',
    'If checked, non-connected sellers will see a notice to connect their MangoPay account on their vendor dashboard.' => 'Wenn diese Option aktiviert ist, werden nicht verbundene Verkäufer auf ihrem Anbieter Dashboard einen Hinweis sehen, ihr MangoPay Account zu verbinden.',
    'If checked, non-connected sellers will see a notice to connect their PayPal account on their vendor dashboard.' => 'Wenn dieses Kontrollkästchen aktiviert ist, wird nicht verbundenen Verkäufern auf ihrem Anbieter Dashboard ein Hinweis angezeigt, ihren PayPal Account zu verbinden.',
    'If checked, non-connected sellers will see a notice to connect their Razorpay account on their vendor dashboard.' => 'Wenn diese Option aktiviert ist, sehen nicht verbundene Verkäufer einen Hinweis, ihr RazorPay Account auf ihrem Anbieter Dashboard zu verbinden.',
    'If checked, non-connected sellers will see a notice to sign up for a Stripe Express account on their vendor dashboard.' => 'Wenn diese Option aktiviert ist, sehen nicht verbundene Verkäufer auf ihrem Anbieter Dashboard einen Hinweis zur Anmeldung für ein Stripe Express Account.',
    'If checked, vendor completes registration only after subscribing to a pack' => 'Wenn angekreuzt, schließt der Anbieter die Registrierung erst ab, nachdem er ein Paket abonniert hat',
    'If Display Notice to Connect Seller' => 'Wenn Anzeige Hinweis zu verbundenen Verkäufer',
    'If enabled, customers will be able to save cards during checkout. Card data will be saved on MangoPay server, not on the store.' => 'Wenn diese Option aktiviert ist, können Kunden während des Bezahlvorgang Karten speichern. Die Kartendaten werden auf dem MangoPay Server gespeichert, nicht im Store.',
    'If enabled, customers will be able to save cards during checkout. Card data will be saved on Stripe server, not on the store.' => 'Wenn diese Option aktiviert ist, können Kunden Karten während des Bezahlvorgangs speichern. Kartendaten werden auf dem Stripe Server gespeichert, nicht im Store.',
    'If enabled, sales earning will add to vendor balance after mentioned number of days.' => 'Wenn diese Option aktiviert ist, wird der Verkaufserlös nach der angegebenen Anzahl von Tagen zum Anbietersaldo hinzugefügt.',
    'If enabled, users will be able to pay using Apple Pay or Chrome Payment Request if supported by the browser. Depending on the web browser and wallet configurations, your customers will see either Apple Pay or Google Pay, but not both.' => 'Wenn diese Option aktiviert ist, können Benutzer mit Apple Pay oder Chrome Payment Request bezahlen, sofern der Browser dies unterstützt. Je nach Webbrowser und Geldbörsen Konfiguration sehen Ihre Kunden entweder Apple Pay oder Google Pay, aber nicht beides.',
    'If enabled, users will be able to pay with a saved card during checkout. Card details are saved on Stripe servers, not on your store.' => 'Wenn diese Option aktiviert ist, können Benutzer an der Kasse mit einer gespeicherten Karte bezahlen. Kartendetails werden auf Stripe Servern gespeichert, nicht in Ihrem Store.',
    'If if you don\'t have one and fill Client ID and Secret below. %1$sCreate an App%2$s' => 'Wenn Sie noch keine haben, geben Sie unten die Client ID und Secret ein. %1$sEine App erstellen%2$s',
    'If it is default address and you change the address, the verification request for the address will be cancelled. Please make sure that you want to change the address.' => 'Wenn es sich um die Standardadresse handelt und Sie die Adresse ändern, wird die Verifizierungsanfrage für die Adresse abgebrochen. Bitte stellen Sie sicher, dass Sie die Adresse ändern möchten.',
    'If managing stock, this controls if backorders are allowed.' => 'Falls die Lagerverwaltung aktiviert ist, können damit Lieferrückstände erlaubt werden.',
    'If not bookable, users won\'t be able to choose this block for their booking.' => 'Wenn nicht buchbar, können Benutzer diesen Block nicht für ihre Buchung auswählen.',
    'If returning a single notice, notice id will be available .' => 'Wenn Sie eine einzelne Benachrichtigung zurücksenden, ist die Benachrichtigung ID verfügbar.',
    'If returning a single notice, vendor id will be available .' => 'Wenn Sie eine einzelne Benachrichtigung zurücksenden, ist die Anbieter ID verfügbar.',
    'If Send Announcement to Connect Seller setting is enabled, non-connected sellers will receive announcement notice to connect their MangoPay account once in a week by default. You can control notice display interval from here. The interval value will be considered in days.' => 'Wenn die Ankündigung an Verbundene Verkäufer senden Einstellung aktiviert ist, erhalten nicht verbundene Verkäufer standardmäßig einmal pro Woche eine Benachrichtigung, um ihr MangoPay Account zu verbinden. Sie können den Intervall für die Anzeige der Benachrichtigung von hier aus steuern. Der Intervallwert wird in Tagen angegeben.',
    'If Send Announcement to Connect Seller setting is enabled, non-connected sellers will receive announcement notice to connect their PayPal account once in a week by default. You can control notice display interval from here.' => 'Wenn die Einstellung Benachrichtigung an verbundene Verkäufer senden aktiviert ist, erhalten nicht verbundene Anbieter standardmäßig einmal pro Woche eine Benachrichtigung zur Verbindung ihres PayPal Accounts. Sie können das Intervall für die Anzeige der Benachrichtigung von hier aus steuern.',
    'If Send Announcement to Connect Seller setting is enabled, non-connected sellers will receive announcement notice to connect their Razorpay account once in a week by default. You can control notice display interval from here.' => 'Wenn die Einstellung Ankündigung an verbundene Verkäufer senden aktiviert ist, erhalten nicht verbundene Verkäufer standardmäßig einmal in der Woche eine Ankündigung, um ihr RazorPay Account zu verbinden. Sie können den Intervall für die Anzeige der Benachrichtigung von hier aus steuern.',
    'If Send Announcement to Connect Seller setting is enabled, non-connected sellers will receive announcement notice to sign up for a Stripe Express account once in a week by default. You can control notice display interval from here. The interval value will be considered in days.' => 'Wenn die Ankündigung senden, um Verkäufer zu verbinden Einstellung aktiviert ist, erhalten nicht verbundene Verkäufer standardmäßig einmal pro Woche eine Ankündigung, sich für ein Stripe Express Account anzumelden. Von hier aus können Sie das Benachrichtigungsanzeigeintervall steuern. Der Intervallwert wird in Tagen berücksichtigt.',
    'If set, it will override global withdraw threshold days for this vendor' => 'Wenn diese Option gesetzt ist, hat sie Vorrang vor den globalen Schwellentagen für diesen Anbieter',
    'If set, specified vendor announcement will be returned.' => 'Wenn festgelegt, wird die angegebene Anbieterankündigung zurückgegeben.',
    'If the product is on sale you may want to show a price label right before outputting the new price to inform the customer.' => 'Wenn das Produkt im Angebot ist, möchten Sie vielleicht ein Preisschild anzeigen, bevor Sie den neuen Preis ausgeben, um den Kunden zu informieren.',
    'If the product is on sale you may want to show a price label right before outputting the old price to inform the customer.' => 'Wenn das Produkt im Angebot ist, möchten Sie vielleicht ein Preisschild anzeigen, bevor Sie den alten Preis ausgeben, um den Kunden zu informieren.',
    'If the shipping price is same for all the states, use this field. If not, manually add the states below' => 'Wenn der Versandpreis für alle Staaten gleich ist, verwenden Sie dieses Feld. Wenn nicht, fügen Sie die folgenden Zustände manuell hinzu',
    'If the variation is downloadable.' => 'Wenn die Variante heruntergeladen werden kann.',
    'If the variation is virtual.' => 'Wenn die Variation virtuell ist.',
    'If there are a mix of classes then the class with the lowest number priority (defined above) will be used.' => 'Wenn es mehrere Klassen gibt, wird die Klasse mit der niedrigsten Priorität (siehe oben) verwendet.',
    'If this is enable, customers can order products from non-connected sellers. The payment will send to admin Stripe account.' => 'Wenn dies aktiviert ist, können Kunden Produkte bei nicht verbundenen Anbietern bestellen. Die Zahlung wird an den Admin Stripe Account gesendet.',
    'If this is enabled and Dokan Stripe Connect is the only gateway available, non-connected sellers will receive announcement notice to connect their Stripe account once in a week.' => 'Wenn dies aktiviert ist und Dokan Stripe Connect das einzige verfügbare Gateway ist, erhalten nicht angeschlossene Verkäufer einmal pro Woche eine Ankündigung, ihr Stripe Account zu verbinden.',
    'If this is enabled non-connected sellers will receive announcement notice to connect their MangoPay account.' => 'Wenn dies aktiviert ist, erhalten nicht verbundene Verkäufer eine Ankündigung, ihr MangoPay Account zu verbinden.',
    'If this is enabled non-connected sellers will receive announcement notice to connect their Paypal account once in a week by default.' => 'Wenn dies aktiviert ist, erhalten nicht verbundene Verkäufer standardmäßig einmal pro Woche eine Ankündigung, ihren PayPal Account zu verbinden.',
    'If this is enabled non-connected sellers will receive announcement notice to connect their Razorpay account once in a week by default.' => 'Wenn dies aktiviert ist, erhalten nicht verbundene Verkäufer standardmäßig einmal pro Woche eine Ankündigung, ihr RazorPay Account zu verbinden.',
    'If this is enabled non-connected sellers will receive announcement notice to sign up for a Stripe Express account.' => 'Wenn dies aktiviert ist, erhalten nicht verbundene Verkäufer eine Ankündigung, sich für ein Stripe Express Account anzumelden.',
    'If this is enabled, non-connected sellers will see a notice to connect their MangoPay account on their vendor dashboard.' => 'Wenn dies aktiviert ist, sehen nicht verbundene Verkäufer einen Hinweis, ihr MangoPay Account auf ihrem Anbieter Dashboard zu verbinden.',
    'If this is enabled, non-connected sellers will see a notice to connect their Paypal account on their vendor dashboard.' => 'Wenn dies aktiviert ist, sehen nicht verbundene Verkäufer auf ihrem Anbieter Dashboard einen Hinweis, ihren PayPal Account zu verbinden.',
    'If this is enabled, non-connected sellers will see a notice to connect their Razorpay account on their vendor dashboard.' => 'Wenn dies aktiviert ist, sehen nicht verbundene Verkäufer einen Hinweis, ihr RazorPay Account auf ihrem Anbieter Dashboard zu verbinden.',
    'If this is enabled, non-connected sellers will see a notice to sign up for a Stripe Express account on their vendor dashboard.' => 'Wenn dies aktiviert ist, sehen nicht verbundene Verkäufer auf ihrem Anbieter Dashboard einen Hinweis, sich für ein Stripe Express Account anzumelden.',
    'If true and if the free shipping method requires a coupon, this coupon will enable free shipping.' => 'Wenn dies zutrifft und für die kostenlose Versandmethode ein Gutschein erforderlich ist, ermöglicht dieser Gutschein den kostenlosen Versand.',
    'If true, the coupon can only be used individually. Other applied coupons will be removed from the cart.' => 'Wenn dies zutrifft, kann der Gutschein nur einzeln verwendet werden. Andere angewendete Gutscheine werden aus dem Warenkorb entfernt.',
    'If true, this coupon will not be applied to items that have sale prices.' => 'Wenn dies zutrifft, wird dieser Gutschein nicht auf Artikel mit Angebot Preisen angewendet.',
    'If unchecked, Admin/Site Owner will pay the Razorpay processing fee instead of Seller.' => 'Wenn nicht aktiviert, zahlt der Administrator/Seiteninhaber die RazorPay Bearbeitungsgebühr anstelle des Verkäufers.',
    'If vendor_id is set, number of level acquired for that vendor, otherwise total acquired levels by all vendors.' => 'Wenn vendor_id gesetzt ist, Anzahl der für diesen Anbieter erworbenen Stufen, ansonsten Summe der von allen Anbietern erworbenen Stufen.',
    'If you check this checkbox, advertised product will be marked as featured. Products will be automatically removed from featured list after advertisement is expired.' => 'Wenn Sie dieses Kontrollkästchen aktivieren, wird das beworbene Produkt als besonders hervorgehoben markiert. Die Produkte werden automatisch aus der Liste der hervorgehoben Produkte entfernt, wenn die Anzeige abgelaufen ist.',
    'If you check this checkbox, advertised products will be displayed on top of the catalog listing eg: shop page, single store page etc.' => 'Wenn Sie dieses Kontrollkästchen aktivieren, werden beworbene Produkte über der Katalogliste angezeigt, z.B.: Store Seite, einzelne Store Seite usw.',
    'If you check this checkbox, vendor will be able to advertise their products without any additional cost based on the plan they are subscribed to.' => 'Wenn Sie dieses Kontrollkästchen ankreuzen, kann der Anbieter seine Produkte ohne zusätzliche Kosten bewerben, je nachdem, welchen Plan er abonniert hat.',
    'If you check this checkbox, vendors will be able to purchase advertisement from product listing and product edit page.' => 'Wenn Sie dieses Kontrollkästchen ankreuzen, können Anbieter von der Produktliste und der Produktbearbeitungsseite aus Werbung kaufen.',
    'If you do not mark the shipment as received within %1$s7%2$s days, it will automatically be updated to %1$s"Received"%2$s status.' => 'Wenn Sie die Sendung nicht innerhalb von %1$s7%2$s Tagen als erhalten markieren, wird sie automatisch auf den Status %1$s"Erhalten"%2$s aktualisiert.',
    'If you don\'t have one and fill App ID and Secret below. %1$sCreate an App%2$s' => 'Wenn Sie noch keine haben, geben Sie unten die App ID und Secret ein. %1$sEine App erstellen%2$s',
    'If you don\'t have one and fill Client ID and Secret below. %1$sCreate an App%2$s' => 'Wenn Sie noch keine haben, geben Sie unten die Client ID und Secret ein. %1$sEine App erstellen%2$s',
    'If you don\'t have one and fill Consumer key and Secret below. %1$sCreate an App%2$s' => 'Wenn Sie noch keine haben, geben Sie unten Consumer Key und Secret ein. %1$sEine App erstellen%2$s',
    'If you enable this setting, each vendor will be able to customize invoice number for their orders.' => 'Wenn Sie diese Einstellung aktivieren, kann jeder Anbieter die Rechnungsnummer für seine Bestellungen selbst festlegen.',
    'If you have received your shipment, please click the link below to mark it as received: ' => 'Wenn Sie Ihre Sendung erhalten haben, klicken Sie bitte auf den folgenden Link, um sie als erhalten zu markieren: ',
    'If you have received your shipment, please click the link below to mark it as received: %1$s' => 'Wenn Sie Ihre Sendung erhalten haben, klicken Sie bitte auf den folgenden Link, um sie als erhalten zu markieren: %1$s',
    'If you need to regenerate variable product variations author IDs based on parent variable products, please click on the button below.' => 'Wenn Sie die Autoren IDs variabler Produktvariationen basierend auf übergeordneten variablen Produkten neu generieren müssen, klicken Sie bitte auf den Button unten.',
    'If you want to configure zone wise shipping then' => 'Wenn Sie den zonenweisen Versand konfigurieren möchten, dann',
    'If you want to sell this product as wholesale then set your setting to the right way' => 'Wenn Sie dieses Produkt als Großhandel verkaufen möchten, stellen Sie die richtige Einstellung ein',
    'If you want to use the previous shipping system then' => 'Wenn Sie das vorherige Versandsystem verwenden möchten, dann',
    'If your billing address has been changed for saved payment methods, be sure to remove any %1$ssaved payment methods%2$s on file and re-add them.' => 'Wenn Ihre Rechnungsadresse für gespeicherte Zahlungsmethoden geändert wurde, entfernen Sie alle %1$sgespeicherten Zahlungsmethoden%2$s und fügen Sie sie erneut hinzu.',
    'Image' => 'Bild',
    'Image alternative text.' => 'Alternativtext für Bild.',
    'Image ID.' => 'Bild ID.',
    'Image name.' => 'Bildname.',
    'Image position. 0 means that the image is featured.' => 'Bildposition. 0 bedeutet, dass dieses Bild das hervorgehobene Bild ist.',
    'Image URL.' => 'Bild URL.',
