    'Important notice: Unsupported Store Currency' => 'Wichtiger Hinweis: Nicht unterstützte Shop Währung',
    'Important: Set Accurate Store Currency in Printful' => 'Wichtig: Genaue Shop Währung in Printful festlegen',
    'In admin renewal failed emailThe automatic recurring payment for order %1$s from %2$s has failed. The customer was sent an email requesting authentication of payment. If the customer does not authenticate the payment, they will be requested by email again %3$s.' => 'Die automatische wiederkehrende Zahlung für die Bestellung %1$s von %2$s ist fehlgeschlagen. Dem Kunden wurde eine E-Mail mit der Aufforderung zur Authentifizierung der Zahlung gesendet. Wenn der Kunde die Zahlung nicht authentifiziert, wird er erneut per E-Mail aufgefordert %3$s.',
    'In case the searched store is not found, the default location will be set on the map.' => 'Falls der gesuchte Store nicht gefunden wird, wird der Standardort auf der Karte festgelegt.',
    'In every' => 'In jedem',
    'In every %d %s(s)' => 'Alle %d %s(s)',
    'In failed renewal authentication emailThe automatic payment to renew your subscription with %1$s has failed. To reactivate the subscription, please login and authorize the renewal from your account page: %2$s' => 'Die automatische Zahlung zur Verlängerung Ihres Abonnements mit %1$s ist fehlgeschlagen. Um das Abonnement zu reaktivieren, melden Sie sich bitte an und autorisieren Sie die Verlängerung auf Ihrer Account Seite: %2$s',
    'In order to be used at checkout, the payment method requires the store currency to be set to one of: %s' => 'Damit die Zahlungsmethode an der Kasse verwendet werden kann, muss die Store Währung auf einen der folgenden Werte eingestellt sein: %s',
    'In Stock' => 'Auf Lager',
    'In stock' => 'Auf Lager',
    'In Stock?' => 'Auf Lager?',
    'In stock?' => 'Auf Lager?',
    'In this type of auction all bidders simultaneously submit sealed bids so that no bidder knows the bid of any other participant. The highest bidder pays the price they submitted. If two bids with same value are placed for auction the one which was placed first wins the auction.' => 'Bei dieser Art von Auktion geben alle Bieter gleichzeitig versiegelte Gebote ab, so dass kein Bieter das Gebot eines anderen Teilnehmers kennt. Der Höchstbietende zahlt den von ihm eingereichten Preis. Wenn zwei Gebote mit demselben Wert zur Auktion abgegeben werden, gewinnt das zuerst abgegebene Gebot die Auktion.',
