    'MangoPay collects platform fees from the marketplace owner. That means, all platform fees will be collected from your commission. If you need information about the amount charged as platform fees, please see the %1$s here. Also, if you want to know how the platform fees are collected, please read their %2$s.' => 'MangoPay erhebt Plattformgebühren vom Marktplatzbesitzer. Das bedeutet, dass alle Plattformgebühren von Ihrer Provision abgezogen werden. Wenn Sie Informationen über den Betrag der Plattformgebühren benötigen, lesen Sie bitte die %1$s hier. Wenn Sie wissen möchten, wie die Plattformgebühren erhoben werden, lesen Sie bitte deren %2$s.',
