    'MangoPay Payin Resource ID: %1$s references WooCommerce Order ID: %2$s which was not paid by bank wire' => 'MangoPay Payin Ressourcen ID: %1$s verweist auf WooCommerce Bestell ID: %2$s, die nicht per Banküberweisung bezahlt wurde',
    'MangoPay Payin Resource ID: %1$s references wrong WooCommerce Order ID: %2$s' => 'MangoPay Payin Ressourcen ID: %1$s verweist auf falsche WooCommerce Bestell ID: %2$s',
