    'Regenerate the order commission value based on the saved data. When an order is placed, the order commission-related data, such as the commission rate, commission type, and additional fee for combined commission, are stored in the corresponding product line item data under the `woocommerce_order_itemmeta` table. By clicking on the regenerate button, the order commission will be recalculated based on these saved values. Note that, fully or partially refunded orders will be ignored.' => 'Erneuern Sie den Bestellprovisionswert basierend auf den gespeicherten Daten. Wenn eine Bestellung aufgegeben wird, werden die mit der Bestellprovision verbundenen Daten, wie Provisionssatz, Provisionsart und zusätzliche Gebühr für kombinierte Provisionen, in den entsprechenden Produktpositionsdaten unter der Tabelle `woocommerce_order_itemmeta` gespeichert. Durch Klicken auf den Neu generieren Button wird die Bestellprovision basierend auf diesen gespeicherten Werten neu berechnet. Beachten Sie, dass vollständig oder teilweise erstattete Bestellungen ignoriert werden.',
