    'These emails are sent to chosen recipient(s) when a vendor send request for refund' => 'Diese E-Mails werden an ausgewählte Empfänger gesendet, wenn ein Anbieter einen Antrag auf Rückerstattung sendet',
    'These emails are sent to vendor when a vendor refund request is canceled' => 'Diese E-Mails werden an den Anbieter gesendet, wenn ein Erstattungsantrag des Anbieters storniert wird',
    'These emails are sent to vendor when a vendor refund request is processed' => 'Diese E-Mails werden an den Anbieter gesendet, wenn eine Anfrage zur Anbieter Rückerstattung bearbeitet wird',
    'These products do not ship to your chosen location.: %s' => 'Diese Produkte werden nicht an den von Ihnen gewählten Standort geliefert: %s',
    'These settings control how the size guide will look on your Single Product Page.' => 'Diese Einstellungen steuern, wie die Größentabelle auf Ihrer einzelnen Produktseite aussieht.',
    'Third Quarter' => 'Drittes Quartal',
    'Third week' => 'Dritte Woche',
    'This %s is not supported yet' => '%s wird noch nicht unterstützt',
    'This booking is awaiting your approval. Please check it and inform the customer if the date is available or not.' => 'Diese Buchung wartet auf Ihre Genehmigung. Bitte überprüfen Sie diese und informieren Sie den Kunden, ob das Datum verfügbar ist oder nicht.',
    'This content contains my private information' => 'Dieser Inhalt enthält meine privaten Daten',
    'This content infringes upon my copyright' => 'Dieser Inhalt verstößt gegen mein Urheberrecht',
    'This content is abusive' => 'Dieser Inhalt ist missbräuchlich',
    'This content is spam' => 'Dieser Inhalt ist Spam',
    'This content is violent' => 'Dieser Inhalt ist gewalttätig',
    'This content should marked as adult' => 'Dieser Inhalt sollte als Nur für Erwachsene markiert sein',
    'This content suggests the author might be risk of hurting themselves' => 'Dieser Inhalt deutet darauf hin, dass der Autor Gefahr läuft, sich selbst zu verletzen',
    'This content will be shown as short product description within checkout and emails.' => 'Dieser Inhalt wird als kurze Produktbeschreibung an der Kasse und in E-Mails angezeigt.',
    'This controls the description which the user sees during checkout.' => 'Dies steuert die Beschreibung, die der Benutzer an der Kasse sieht.',
    'This controls the title which the user sees during checkout.' => 'Dies steuert den Titel, den der Benutzer an der Kasse sieht.',
    'This controls the title which the user sees during checkout. This title will be shown only when multiple payment methods are enabled for Stripe Express' => 'Dies steuert den Titel, den der Benutzer während der Kaufabwicklung sieht. Dieser Titel wird nur angezeigt, wenn mehrere Zahlungsarten für Stripe Express aktiviert sind',
    'This coupon is a discount offered by a vendor based on order totals.' => 'Bei diesem Gutschein handelt es sich um einen vom Anbieter gewährten Rabatt auf den Gesamtbestellwert.',
    'This coupon is a discount offered by a vendor on their products based on the quantity purchased.' => 'Bei diesem Gutschein handelt es sich um einen von einem Anbieter auf seine Produkte gewährten Rabatt, der von der gekauften Menge abhängt.',
    'This determines the order when there are multiple add-ons. Add-ons for individual products are set to order 10.' => 'Dies bestimmt die Reihenfolge, wenn mehrere Addons vorhanden sind. Addons für einzelne Produkte werden auf Reihenfolge 10 eingestellt.',
    'This email is sent to a customer when a Question is answered by vendor.' => 'Diese E-Mail wird an einen Kunden gesendet, wenn eine Frage vom Anbieter beantwortet wird.',
    'This email is sent to a to chosen recipient(s) when a Question is asked by customer.' => 'Diese E-Mail wird an einen oder mehrere ausgewählte Empfänger gesendet, wenn ein Kunde eine Frage stellt.',
    'This email is sent to a vendor when a Question is asked by customer.' => 'Diese E-Mail wird an einen Anbieter gesendet, wenn ein Kunde eine Frage stellt.',
    'This email is sent to admin and vendor when booking is cancelled by the customer' => 'Diese E-Mail wird an den Administrator und den Anbieter gesendet, wenn die Buchung vom Kunden storniert wird',
    'This email is sent to admin when customer register as a wholesale customer' => 'Diese E-Mail wird an den Administrator gesendet, wenn sich der Kunde als Großhandelskunde registriert',
    'This email is sent to admin when vendors cancel their subscriptions' => 'Diese E-Mail wird an den Administrator gesendet, wenn Anbieter ihre Abonnements kündigen',
    'This email is set to a customer when add new shipping status on their order' => 'Diese E-Mail wird an einen Kunden gesendet, wenn ein neuer Versandstatus zu seiner Bestellung hinzugefügt wird',
    'This email is set to a vendor when a `payment action is required` for subscription renew.' => 'Diese E-Mail wird an einen Anbieter gesendet, wenn für die Verlängerung des Abonnements eine Zahlungsaktion erforderlich ist.',
    'This email is set to a vendor when he enabled from admin settings' => 'Diese E-Mail wird an einen Anbieter gesendet, wenn er diese über die Administratoreinstellungen aktiviert hat',
    'This email is set to a vendor when his account is deactivated by admin' => 'Diese E-Mail wird an einen Anbieter gesendet, wenn sein Account vom Administrator deaktiviert wird',
    'This email is set to be sent to a vendor when a `payment action is required` for subscription renew.' => 'Diese E-Mail wird an einen Anbieter gesendet, wenn eine `Zahlungsaktion` für die Verlängerung des Abonnements erforderlich ist.',
    'This email send to customer when customer send return request and vendor send a store credit to customer' => 'Diese E-Mail wird an den Kunden gesendet, wenn der Kunde eine Rückgabeanforderung sendet und der Anbieter dem Kunden eine Store Gutschrift sendet',
    'This email send to vendor once customer request for a refund' => 'Diese E-Mail wird an den Anbieter gesendet, sobald der Kunde eine Rückerstattung beantragt hat',
    'This email send to vendor or customer once customer or vendor make a new conversation on request for a refund' => 'Diese E-Mail wird an den Anbieter gesendet, sobald der Kunde eine Rückerstattung beantragt hat',
    'This email was sent to %1$s.' => 'Diese E-Mail wurde an %1$s gesendet.',
    'This email will be sent to the admin after submitting documents by a vendor for verification.' => 'Diese E-Mail wird an den Administrator gesendet, nachdem ein Anbieter Dokumente zur Verifizierung übermittelt hat.',
    'This email will be sent to the customer of the corresponding order if the vendor has updated the delivery time.' => 'Diese E-Mail wird an den Kunden der entsprechenden Bestellung gesendet, wenn der Anbieter die Lieferzeit aktualisiert hat.',
    'This email will be sent to the vendor & the recipient of the corresponding order has been received by the customer.' => 'Diese E-Mail wird an den Anbieter & den Empfänger der entsprechenden Bestellung gesendet, wenn diese beim Kunden eingegangen ist.',
    'This email will be sent to the vendor after updating verification request by admin.' => 'Diese E-Mail wird an den Anbieter gesendet, nachdem der Administrator den Verifizierungsstatus aktualisiert hat.',
    'This email will be sent to the vendor and customer of the corresponding order if the admin has updated the delivery time.' => 'Diese E-Mail wird an den Anbieter und den Kunden der entsprechenden Bestellung gesendet, wenn der Administrator die Lieferzeit aktualisiert hat.',
    'This feature allows administrators to automatically disconnect vendor accounts from restricted countries or regions. By specifying a list of restricted locations, the system will identify and bulk disconnect any existing vendor accounts associated with those areas.' => 'Mit dieser Funktion können Administratoren Anbieter Accounts aus eingeschränkten Ländern oder Regionen automatisch trennen. Durch die Angabe einer Liste eingeschränkter Standorte identifiziert das System alle bestehenden Anbieter Accounts, die mit diesen Gebieten verknüpft sind, und trennt sie in großen Mengen.',
    'This file is too big. Maximum 10MB allowed for %s' => 'Diese Datei ist zu groß. Maximal 10MB zulässig für %s',
    'This file is too small. Minimum 1KB required for %s' => 'Diese Datei ist zu klein. Minimum 1KB erforderlich für %s',
    'This file is too small. Minimum 32KB required for %s' => 'Diese Datei ist zu klein. Minimum 32KB erforderlich für %s',
    'This function should not be called before woocommerce_init.' => 'Diese Funktion sollte nicht vor woocommerce_init aufgerufen werden.',
    'This gateway is not supported yet' => 'Dieses Gateway wird noch nicht unterstützt',
    'This info will show on checkout page delivery time box. %s will be replaced by delivery blocked buffer' => 'Diese Information wird auf der Kasse Seite angezeigt. %s wird durch den blockierten Lieferpuffer ersetzt',
    'This is a list of pending vendors who have registered in the marketplace but not active yet. Make them active to enable selling.' => 'Dies ist eine Liste ausstehender Anbieter, die sich auf dem Markt registriert haben, aber noch nicht aktiv sind. Aktivieren Sie sie, um den Verkauf zu ermöglichen.',
    'This is an optional settings that will add Analytics Global Site Tag in you site header. If you use any SEO plugin or add your tracking code by other means, then choose `no` in the settings.' => 'Dies ist eine optionale Einstellung, mit der Analytics Global Site Tag in Ihre Seiten Kopfzeile eingefügt wird. Wenn Sie ein SEO Plugin verwenden oder Ihren Tracking Code auf andere Weise hinzufügen, wählen Sie in den Einstellungen "Nein".',
    'This is not yours, I swear!' => 'Das ist nicht Ihres, ich garantiere!',
    'This is simple product import and export plugin for vendor' => 'Dies ist ein einfaches Plugin zum Importieren und Exportieren von Produkten für Anbieter',
    'This is the Auth Key you set in ShipStation and allows ShipStation to communicate with your store.' => 'Dies ist der Authentifizierung Key, den Sie in ShipStation festgelegt haben und der es ShipStation ermöglicht, mit Ihrem Store zu kommunizieren.',
    'This is the base price and will be the starting shipping price for each product' => 'Dies ist der Grundpreis und der Startversandpreis für jedes Produkt',
    'This is the cost per block booked. All other costs (for resources and persons) are added to this.' => 'Dies sind die Kosten pro gebuchtem Block. Alle anderen Kosten (für Ressourcen und Personen) werden dazu addiert.',
    'This is the name of the download shown to the customer.' => 'Name des Downloads, der dem Kunden angezeigt wird.',
    'This is the number that will be used for the next document. By default, numbering starts from 1 and increases for every new document. Note that if you override this and set it lower than the current/highest number, this could create duplicate numbers!' => 'Dies ist die Nummer, die für das nächste Dokument verwendet wird. Standardmäßig beginnt die Nummerierung bei 1 und wird für jedes neue Dokument erhöht. Beachten Sie, dass, wenn Sie diesen Wert überschreiben und ihn niedriger als die aktuelle/höchste Nummer einstellen, dies zu doppelten Nummern führen kann!',
    'This is the shipping and handling total costs for the order.' => 'Dies sind die Gesamtkosten für Versand und Bearbeitung der Bestellung.',
    'This is the sum of the order totals after any refunds and excluding shipping and taxes.' => 'Dies ist die Summe des Bestellwerts nach Abzug aller Rückerstattungen und ohne Versand und Steuern.',
    'This is the sum of the order totals after any refunds and including shipping and taxes.' => 'Dies ist die Summe des Bestellwerts abzüglich etwaiger Rückerstattungen und einschließlich Versand und Steuern.',
    'This is the total discount. Discounts are defined per line item.' => 'Dies ist der Gesamtrabatt. Rabatte werden pro Werbebuchung definiert.',
    'This is the URL or absolute path to the file which customers will get access to.' => 'Die URL oder der absolute Pfad zu der Datei, zu der die Kunden Zugang erhalten.',
    'This is the URL or absolute path to the file which customers will get access to. URLs entered here should already be encoded.' => 'Dies ist die URL oder der absolute Pfad zu der Datei, auf die Kunden zugreifen können. Hier eingegebene URLs sollten bereits verschlüsselt sein.',
    'This is where you define your table rates which are applied to an order.' => 'Hier legen Sie Ihre Tabellensätze fest, die auf eine Bestellung angewendet werden.',
    'This item will be shipped by Printful.' => 'Dieser Artikel wird von Printful versendet.',
    'This label will show on checkout page' => 'Dieses Beschriftung wird auf der Kassenseite angezeigt',
    'This lets you choose which products are part of this group.' => 'Auf diese Weise können Sie auswählen, welche Produkte zu dieser Gruppe gehören.',
    'This month' => 'Diesen Monat',
    'This month\'s sales' => 'Verkäufe diesen Monat',
    'This name is for your reference only and will not be visible to customers.' => 'Dieser Name dient nur als Referenz und ist für Kunden nicht sichtbar.',
    'This notice will be shown after a user has registered with pending email verification.' => 'Dieser Hinweis wird angezeigt, nachdem sich ein Benutzer mit ausstehender E-Mail Bestätigung registriert hat.',
    'This notice will be shown when a user tries to login without email verification.' => 'Dieser Hinweis wird angezeigt, wenn ein Benutzer versucht, sich ohne E-Mail Bestätigung anzumelden.',
    'This number is blocked for your account.' => 'Diese Nummer ist für Ihren Account gesperrt.',
    'This number is incapable of receiving SMS messages.' => 'Diese Nummer ist nicht in der Lage, SMS zu empfangen.',
    'This option affects how bookings are checked for availability.' => 'Diese Option wirkt sich darauf aus, wie Buchungen auf Verfügbarkeit geprüft werden.',
    'This option affects how you use the rules below.' => 'Diese Option wirkt sich darauf aus, wie Sie die folgenden Regeln verwenden.',
    'This option disables the "plus shipping costs" notice on product page.' => 'Mit dieser Option wird der Hinweis "zuzüglich Versandkosten" auf der Produktseite deaktiviert.',
    'This order has been processed using the Mangopay Sandbox environment.' => 'Diese Bestellung wurde in der MangoPay Sandbox Umgebung bearbeitet.',
    'This page contains your store-wide shipping settings, costs, shipping and refund policy.' => 'Diese Seite enthält Ihre Storeweiten Versandeinstellungen, Kosten, Versand- und Rückerstattungsrichtlinien.',
    'This payment method is not available on the selected country' => 'Diese Zahlungsmethode ist im ausgewählten Land nicht verfügbar',
    'This payment method is not supported yet' => 'Diese Zahlungsmethode wird noch nicht unterstützt',
    'This product does not ship to your chosen location: %s' => 'Dieses Produkt wird nicht an den von Ihnen gewählten Standort geliefert: %s',
    'This product has no abuse report' => 'Dieses Produkt hat keine Missbrauch Meldung',
    'This product requires shipping' => 'Dieses Produkt muss versendet werden',
    'This quote is already converted into order.' => 'Dieses Angebot ist bereits in eine Bestellung umgewandelt.',
    'This refund is failed to process.' => 'Diese Erstattung wurde nicht bearbeitet.',
    'This refund is not allowed to approve' => 'Diese Rückerstattung kann nicht genehmigt werden',
    'This request is awaiting your approval. Please check it and inform the customer if he is eligble or not.' => 'Diese Anfrage wartet auf Ihre Genehmigung. Bitte überprüfen Sie dies und informieren Sie den Kunden, ob er berechtigt ist oder nicht.',
    'This setting enables vendors to set discounts based on the quantity of items ordered from a specific vendor. Also, vendor can set a discount percentage which will be applied to the total order amount.' => 'Mit dieser Einstellung können Anbieter Rabatte basierend auf der Menge der von einem bestimmten Anbieter bestellten Artikel festlegen. Außerdem kann der Anbieter einen Rabattprozentsatz festlegen, der auf den Gesamtbestellbetrag angewendet wird.',
    'This setting is being overridden at the resource level.' => 'Diese Einstellung wird auf Ressourcenebene überschrieben.',
    'This store needs %s day(s) to process your delivery request' => 'Dieser Store benötigt %s Tag(e), um Ihren Lieferauftrag zu bearbeiten',
    'This text will be shown on the button linking to the external product.' => 'Dieser Text wird auf dem Butten angezeigt, der auf das externe Produkt verweist.',
    'This ticket has been closed. Open a new support ticket if you have any further query.' => 'Dieses Ticket wurde geschlossen. Öffnen Sie ein neues Support Ticket, wenn Sie weitere Fragen haben.',
    'This ticket is closed.' => 'Dieses Ticket ist geschlossen.',
    'This tool allows you to generate and download a CSV file containing a list of all products.' => 'Mit diesem Tool können Sie eine CSV Datei mit einer Liste aller Produkte erstellen und herunterladen.',
    'This tool allows you to import (or merge) product data to your store from a CSV or TXT file.' => 'Mit diesem Tool können Sie Produktdaten aus einer CSV- oder TXT Datei in Ihren Store importieren (oder zusammenführen).',
    'This tool allows you to import vendor and some products for vendors to your marketplace.' => 'Mit diesem Tool können Sie Anbieter und einige Produkte für Anbieter in Ihren Marktplatz importieren.',
    'This tool will check for duplicate orders from the Dokan\'s sync table.' => 'Dieses Tool sucht in der Synchronisierungstabelle des Dokan nach doppelten Bestellungen.',
    'This transaction requires authentication.' => 'Diese Transaktion erfordert eine Authentifizierung.',
    'This user already has recurring pack assigned. Are you sure to assign a new normal pack to the user? If you do so, the existing recurring plan will be replaced with the new one' => 'Diesem Benutzer wurde bereits ein wiederkehrendes Paket zugewiesen. Sind Sie sicher, dass Sie dem Benutzer ein neues normales Paket zuweisen wollen? Wenn Sie dies tun, wird der bestehende wiederkehrende Plan durch den neuen ersetzt',
    'This webhook is created by Dokan Pro.' => 'Dieser Webhook wurde von Dokan Pro erstellt.',
    'This will add a new section in vendor product edit page with fields provided by Germanized for WooCommerce plugin' => 'Dies fügt einen neuen Abschnitt auf der Produktbearbeitungsseite des Anbieters mit Feldern hinzu, die vom Germanized for WooCommerce Plugin bereitgestellt werden',
    'This will be displayed in SMS. %1$s%%CODE%%%2$s will be replaced by verification code' => 'Dies wird in SMS angezeigt. %1$s%%CODE%%%2$s wird durch den Bestätigungscode ersetzt',
    'This will be the title of the custom withdraw method. e.g. MoneyGram' => 'Dies ist der Titel der benutzerdefinierten Auszahlungsmethode. z.B. MoneyGram',
    'This will reject the product and notify the vendor. Are you sure?' => 'Dadurch wird das Produkt abgelehnt und der Verkäufer benachrichtigt. Sind Sie sicher?',
    'Thumbnail' => 'Thumbnail',
    'Thursday' => 'Donnerstag',
    'Ticket Closed' => 'Ticket geschlossen',
    'Ticket ID or Keyword' => 'Ticket ID oder Keyword',
    'Ticket ID:' => 'Ticket ID:',
    'Ticket is %s' => 'Ticket ist %s',
    'Ticket status' => 'Ticket Status',
    'Ticket summary' => 'Ticket Zusammenfassung',
    'Ticket URL :' => 'Ticket URL :',
    'Ticket URL: ' => 'Ticket URL: ',
    'Time' => 'Zeit',
    'Time Range' => 'Zeitraum',
    'Time Range (all week)' => 'Zeitraum (ganze Woche)',
    'Time Ranges' => 'Zeitauswahl',
    'Time Slot' => 'Zeitfenster',
    'Time slot' => 'Zeitfenster',
    'Time slot in minutes. Please keep opening and closing time divisible by slot minutes. E.g ( 30, 60, 120 )' => 'Zeitfenster in Minuten. Bitte halten Sie die Öffnungs- und Schließzeit durch die Minuten des Zeitfensters teilbar. Z.B. ( 30, 60, 120 )',
    'Time slot in minutes. Please keep opening and closing time divisible by slot minutes. E.g ( 30, 60, 120 ). Also this cannot be empty, less then 10 or greater then 1440 minutes.' => 'Zeitfenster in Minuten. Bitte achten Sie darauf, dass die Öffnungs- und Schließzeit durch die Minuten des Zeitfensters teilbar ist. Z. B. (30, 60, 120). Außerdem darf dieses Feld nicht leer sein und darf nicht weniger als 10 oder mehr als 1440 Minuten betragen.',
    'Time slot minutes can not be empty, less than 10 minutes or greater than 1440 minutes' => 'Die Minuten des Zeitfensters dürfen nicht leer sein, weniger als 10 Minuten oder mehr als 1440 Minuten betragen',
    'Time Zone' => 'Zeitzone',
    'Title' => 'Titel',
    'Title :' => 'Titel :',
    'Title of the advertised product' => 'Titel des beworbenen Produkts',
    'Title of the Announcement' => 'Titel der Ankündigung',
    'Title of the quote.' => 'Titel des Angebots.',
    'Title of the resource.' => 'Titel der Ressource.',
    'Title:' => 'Titel:',
    'Title: ' => 'Titel: ',
    'TNT Express (consignment)' => 'TNT Express (Sendung)',
    'TNT Express (reference)' => 'TNT Express (Referenz)',
    'To' => 'Bis',
    'to' => 'zu',
    'To %1$s your subscription %2$s click here &rarr;' => 'Um Dein Abonnement zu beenden, klicke hier &rarr;',
    'To be advertise product id.' => 'Zu werbende Produkt ID.',
    'To change your store currency, please go to <a href="%s">Woocommerce General Settings</a>.' => 'Um Ihre Store Währung zu ändern, gehen Sie bitte zu den <a href="%s">Allgemeinen Einstellungen von WooCommerce</a>.',
    'To complete your order, please do a bank transfer with the following information, including the bank wire reference.' => 'Um Ihre Bestellung abzuschließen, bitten wir Sie um eine Banküberweisung mit den folgenden Informationen, einschließlich der Banküberweisungsreferenz.',
    'To complete your transaction with **the selected payment method**, you must log in or create an account with our site.' => 'Um Ihre Transaktion mit der **ausgewählten Zahlungsmethode** abzuschließen, müssen Sie sich einloggen oder ein Account auf unserer Webseite erstellen.',
    'To continue selling products and receiving payouts, we encourage you to connect one of the other available payment methods on our platform. This will ensure a seamless experience for you and your customers during the checkout process.' => 'Damit Sie weiterhin Produkte verkaufen und Auszahlungen erhalten können, empfehlen wir Ihnen, eine der anderen auf unserer Plattform verfügbaren Zahlungsmethoden zu verbinden. Dies gewährleistet ein nahtloses Erlebnis für Sie und Ihre Kunden während des Bezahlvorgangs.',
    'to duplicate products image, content, attributes, tags etc' => 'Bilder, Inhalte, Attribute, Tags usw. von Produkten zu duplizieren',
    'To edit your product, visit: %s' => 'Um Ihr Produkt zu bearbeiten, besuchen Sie: %s',
    'To enable Prinful correctly, assign Shipping Fee Recipient, and Shipping Tax Fee Recipient to individual vendors. This integration requires that each vendor will manage and fulfill their orders using their Printful account.' => 'Um Prinful richtig zu aktivieren, weisen Sie den Empfänger der Versandgebühr und der Versandsteuergebühr einzelnen Anbieter zu. Diese Integration erfordert, dass jeder Anbieter seine Bestellungen über sein Printful Account verwaltet und ausführt.',
    'To enable unit prices on variation level please choose a unit and unit price units within %s.' => 'Um Einheitspreise auf Variationsebene zu aktivieren, wählen Sie bitte eine Einheit und Einheitspreiseinheiten innerhalb von %s.',
    'To ensure accurate pricing and successful integration, please select one of the Printful supported currencies from <strong>WooCommerce → Settings → General → Currency</strong>, under <strong>Currency Options</strong>. Please select one of these currencies to match Printful: <b>USD, EUR, GBP, CAD, JPY, AUD, BRL, CHF, DKK, HKD, MXN, NZD, SEK</b>.' => 'Um genaue Preise und eine erfolgreiche Integration sicherzustellen, wählen Sie bitte eine der von Printful unterstützten Währungen aus <strong>WooCommerce → Einstellungen → Allgemein → Währung</strong> unter <strong>Währungsoptionen</strong>. Bitte wählen Sie eine dieser Währungen passend zu Printful aus: <b>USD, EUR, GBP, CAD, JPY, AUD, BRL, CHF, DKK, HKD, MXN, NZD, SEK</b>.',
    'To get Merchant ID goto Paypal Dashboard --> Account Settings --> Business Information section.' => 'Um die Merchant ID zu erhalten, gehen Sie zu PayPal Dashboard --> Account Einstellungen --> Abschnitt Geschäftsinformationen.',
    'To make split payment enabled, you must <strong>Activate Route Transfer</strong> from Razorpay Dashboard <a href="%1$s" target="_blank">here</a>.' => 'Um die geteilte Zahlung zu aktivieren, müssen Sie im RazorPay Dashboard <a href="%1$s" target="_blank">hier</a> <strong>Routenübertragung aktivieren</strong>.',
    'to use the invoice year and/or month, use [invoice_year] or [invoice_month] respectively' => 'um das Rechnungsjahr und/oder den Monat zu verwenden, verwenden Sie [invoice_year] bzw. [invoice_month]',
    'To use this account, just write it below or give any razorpay account ID.' => 'Um diesen Account zu verwenden, schreiben Sie es einfach unten oder geben Sie eine beliebige RazorPay Account ID an.',
    'To zoom in increase the number, to zoom out decrease the number.' => 'Zum Vergrößern erhöhen Sie die Zahl, zum Verkleinern verringern Sie die Zahl.',
    'Toggle Status' => 'Toggle Status',
    'Token is empty' => 'Token ist leer',
    'Token processing error' => 'Fehler bei der Token Verarbeitung',
    'Tolls' => 'Mautstellen',
