    'You can check it out by following the URL below.' => 'Sie können es ausprobieren, indem Sie der folgenden URL folgen.',
    'You can check out it by going <a href="%s">here</a>.' => 'Sie können es <a href="%s">hier</a> ausprobieren.',
    'You can check this announcement in dashboard by clicking <a href="%s">here<a/>.' => 'Sie können diese Ankündigung im Dashboard überprüfen, indem Sie hier <a href="%s">hier<a/> klicken',
    'You can check this announcement in your dashboard ' => 'Sie können diese Ankündigung in Ihrem Dashboard überprüfen ',
    'You can check this reply by clicking <a href="%s">here<a/>.' => 'Sie können die Bestelldetails anzeigen, indem Sie <a href="%s">hier</a> klicken.',
    'You can check this reply by clicking the url below.' => 'Sie können diese Antwort überprüfen, indem Sie auf die folgende URL klicken.',
    'You can choose when whether you want to transfer funds to vendors after the order is completed, or immediately after the payment is completed, or delay the transfer even if the order is processing or completed.' => 'Sie können wählen, ob Sie den Betrag nach Abschluss der Bestellung oder sofort nach Abschluss der Zahlung an den Anbieter überweisen möchten oder ob Sie die Überweisung verzögern möchten, auch wenn die Bestellung in Bearbeitung oder abgeschlossen ist.',
    'You can color your vendor dashboard by choosing any color as your brand identity or as your wish.' => 'Sie können Ihr Anbieter Dashboard in einer beliebigen Farbe einfärben, die Ihrer Markenidentität oder Ihren Wünschen entspricht.',
    'You can configure how and where store support settings are displayed in your site.' => 'Sie können konfigurieren, wie und wo die Support Einstellungen Ihres Store auf Ihrer Webseite angezeigt werden.',
    'You can configure settings to allow customers to track their products.' => 'Sie können Einstellungen konfigurieren, die es Kunden ermöglichen, ihre Produkte zu verfolgen.',
    'You can configure wholesale settings for your store and allow vendors to operate on wholesale price and quantity.' => 'Sie können Großhandelseinstellungen für Ihren Store konfigurieren und Anbietern erlauben, mit Großhandelspreisen und -mengen zu arbeiten.',
    'You can configure your general site settings with the option to adjust the color of your dashboard.' => 'Sie können Ihre allgemeinen Webseite Einstellungen mit der Option konfigurieren, die Farbe Ihres Dashboards anzupassen.',
    'You can configure your site settings for customers to utilize when navigating stores for specific products.' => 'Sie können Ihre Webseite Einstellungen so konfigurieren, dass Ihre Kunden bei der Navigation durch die Stores nach bestimmten Produkten suchen können.',
    'You can configure your site settings to allow vendors to offer customized return and warranty facility on their sold products.' => 'Sie können Ihre Webseite Einstellungen so konfigurieren, dass Anbieter die Möglichkeit haben, individuelle Rückgabe- und Garantie Funktionen für ihre verkauften Produkte anzubieten.',
    'You can configure your site to allow customers to choose the time and date they want their products delivered.' => 'Sie können Ihre Webseite so konfigurieren, dass Kunden die Uhrzeit und das Datum auswählen können, an dem sie ihre Produkte geliefert bekommen möchten.',
    'You can configure your site to allow customers to send customized quotes on the selected products.' => 'Sie können Ihre Webseite so konfigurieren, dass Kunden individuelle Angebote für die ausgewählten Produkte senden können.',
    'You can configure your site to allow vendors to sell other vendor\'s products with desired customizations.' => 'Sie können Ihre Webseite so konfigurieren, dass Anbieter die Produkte anderer Anbieter mit den gewünschten Anpassungen verkaufen können.',
    'You can configure your store location settings and access configuration for vendor store from this settings menu.' => 'In diesem Einstellungsmenü können Sie die Einstellungen für den Standort Ihres Store und die Zugangskonfiguration für den Anbieter Store konfigurieren.',
    'You can create a new booking for a customer here. This form will create a booking for the user, and optionally an associated order. Created orders will be marked as pending payment.' => 'Hier können Sie eine neue Buchung für einen Kunden erstellen. Dieses Formular erstellt eine Buchung für den Benutzer und optional einen zugehörigen Auftrag. Erstellte Aufträge werden als zur Zahlung anstehend markiert.',
    'You can create additional <a href="%s">add-ons</a> that apply to all products or to certain categories.' => 'Sie können zusätzliche <a href="%s">Addons</a> erstellen, die für alle Produkte oder bestimmte Kategorien gelten.',
    'You can draft or remove the product or you can ignore this email if you think the product is OK.' => 'Sie können das Produkt entwerfen oder entfernen oder diese E-Mail ignorieren, wenn Sie der Meinung sind, dass das Produkt in Ordnung ist.',
    'You can enable/disable shipping for your products. Also you can override these shipping costs while creating or editing a product.' => 'Sie können den Versand Ihrer Produkte aktivieren/deaktivieren. Sie können diese Versandkosten auch beim Erstellen oder Bearbeiten eines Produkts überschreiben.',
    'You can get it from Apple Developer platform -> login -> Certificates, IDs & Profiles -> Indentifiers -> Service IDs (drop down) -> Register for Service ID -> Collect Service ID.' => 'Sie erhalten sie über die Apple Entwicklerplattform -> Anmeldung -> Zertifikate, IDs & Profile -> Bezeichner -> Service-IDs (Dropdown) -> Für Service ID registrieren -> Service ID.',
    'You can get it from Apple Developer platform -> login -> Certificates, IDs & Profiles -> Keys -> Click " + " -> Register for new Key -> Download "Apple Key Content" -> Collect Key Content.' => 'Sie erhalten ihn über die Apple Entwicklerplattform -> Anmeldung -> Zertifikate, IDs & Profil -> Keys -> Klicken Sie auf " + " -> Registrieren für einen neuen Key -> Laden Sie "Apple Key Content" herunter -> Key Inhalt.',
    'You can get it from Apple Developer platform -> login -> Certificates, IDs & Profiles -> Keys -> Click " + " -> Register for new Key -> Download "Apple Key Content" -> Collect Key ID.' => 'Sie erhalten ihn über die Apple Entwicklerplattform -> Anmeldung -> Zertifikate, IDs & Profil -> Keys -> Klicken Sie auf " + " -> Registrieren für einen neuen Key -> Laden Sie "Apple Key Content" herunter -> Key ID.',
    'You can get it from Apple Developer platform -> login -> Membership ->  Collect Team ID.' => 'Sie erhalten sie über die Apple Entwicklerplattform -> Anmeldung -> Mitgliedschaft -> Team ID.',
    'You can get it from Facebook Developer platform -> Login -> Select  "Add A New App" -> Collect App ID.' => 'Sie erhalten sie über die Facebook Entwicklerplattform -> Anmeldung -> Wählen Sie "Neue App hinzufügen" -> App ID.',
    'You can get it from Facebook Developer platform -> Login -> Select  "Add A New App" -> Collect App secret.' => 'Sie erhalten es über die Facebook Entwicklerplattform -> Anmeldung -> Wählen Sie "Neue App hinzufügen" -> App Secret.',
    'You can get it from Facebook Developer platform -> Login -> Select  "Add A New App" -> Collect Client ID.' => 'Sie erhalten es von der Facebook Entwicklerplattform -> Anmelden -> "Neue App hinzufügen" auswählen -> Client ID erfassen.',
    'You can get it from Google Console Platform -> Google+API -> Enable -> Manage -> Credentials -> Create Credentials -> OAuth client ID -> Web Application -> Fill in the information & click Create. A pop up will show "Client Credentials".' => 'Sie erhalten sie über Google Console Platform -> Google+API -> Enable -> Manage -> Credentials -> Create Credentials -> OAuth client ID -> Web Application -> Füllen Sie die Informationen aus und klicken Sie auf Erstellen. In einem Popup Fenster wird "Client Credentials" angezeigt.',
    'You can get it from Google Console Platform -> Google+API -> Enable -> Manage -> Credentials -> Create Credentials -> OAuth client ID -> Web Application -> Fill in the information & click Create. A pop up will show "Client ID".' => 'Sie erhalten sie über Google Console Platform -> Google+API -> Enable -> Manage -> Credentials -> Create Credentials -> OAuth client ID -> Web Application -> Füllen Sie die Informationen aus und klicken Sie auf Erstellen. In einem Popup Fenster wird "Client ID" angezeigt.',
    'You can get it from https://www.twilio.com/ -> Create an Account -> Collect SID.' => 'Sie erhalten sie unter https://www.twilio.com/ -> Create an Account -> Collect SID.',
    'You can get it from https://www.twilio.com/ -> Create an Account -> Collect Token.' => 'Sie erhalten es unter https://www.twilio.com/ -> Create an Account -> Collect Token.',
    'You can get it from https://www.vonage.com/ -> Create an Account -> Collect Key.' => 'Sie können es von https://www.vonage.com/ -> Account erstellen -> Key sammeln erhalten.',
    'You can get it from https://www.vonage.com/ -> Create an Account -> Collect Secret.' => 'Sie können es von https://www.vonage.com/ -> Account erstellen -> Secret sammeln erhalten.',
    'You can get it from LinkedIn Developers platform -> Create an App -> Fill necessary info -> Click "Create app" -> "Auth" section -> Collect Client ID.' => 'Sie erhalten sie über die Plattform LinkedIn Developers -> App erstellen -> Füllen Sie die erforderlichen Informationen aus -> Klicken Sie auf "App erstellen" -> Abschnitt "Auth" -> Client ID.',
    'You can get it from LinkedIn Developers platform -> Create an App -> Fill necessary info -> Click "Create app" -> "Auth" section -> Collect Client Secret.' => 'Sie erhalten sie über die Plattform LinkedIn Developers -> App erstellen -> Füllen Sie die erforderlichen Informationen aus -> Klicken Sie auf "App erstellen" -> Abschnitt "Auth" -> Client Secret.',
    'You can get it from Twitter Developer platform -> Login -> Select  "Create an App" -> Input URL & integrate Twitter with Dokan. Go to "Keys and Tokens" -> View Keys -> Collect API key and use as Consumer Key.' => 'Sie erhalten ihn über die Twitter Entwicklerplattform -> Anmelden -> Wählen Sie "App erstellen" -> URL eingeben und Twitter mit Dokan integrieren. Gehen Sie zu "Keys and Tokens" -> View Keys -> API Key und als Kunden Key verwenden.',
    'You can get it from Twitter Developer platform -> Login -> Select  "Create an App" -> Input URL & integrate Twitter with Dokan. Go to "Keys and Tokens" -> View Keys -> Collect API secret and use as Consumer secret.' => 'Sie erhalten es von der Twitter Entwicklerplattform -> Anmelden -> Wählen Sie "App erstellen" -> URL eingeben & Twitter mit Dokan integrieren. Gehen Sie zu "Keys and Tokens" -> View Keys -> API Key und als Kunden Key verwenden.',
    'You can integrate and set up your site to let registered and customers chat in real-time with vendors.' => 'Sie können Ihre Webseite integrieren und so einrichten, dass registrierte Kunden in Echtzeit mit den Anbietern chatten können.',
    'You can integrate SMS gateways to verify the contact information of the vendor.' => 'Sie können SMS Gateways integrieren, um die Kontaktinformationen des Anbieters zu überprüfen.',
    'You can not advertise this product. Product needs to be published before you can advertise.' => 'Du kannst dieses Produkt nicht bewerben. Das Produkt muss veröffentlicht werden, bevor Du boosten kannst.',
    'You can not advertise this product. Products need to be published before you can advertise.' => 'Du kannst dieses Produkt nicht bewerben. Produkte müssen veröffentlicht werden, bevor Du sie boosten kannst.',
    'You can not advertise this product. Products needs to be published before you can advertise.' => 'Du kannst dieses Produkt nicht bewerben. Produkte müssen veröffentlicht werden, bevor Du boosten kannst.',
    'You can not change event type.' => 'Sie können den Ereignis Typ nicht ändern.',
    'You can not edit reviews!' => 'Sie können keine Rezensionen bearbeiten!',
    'You can not refund orders that have suborders. Please refund from specific suborders.' => 'Sie können keine Bestellungen erstatten, die Unterbestellungen enthalten. Bitte erstatten Sie von bestimmten Unterbestellungen.',
    'You can only assign non-recurring packs' => 'Sie können nur einmalige Pakete zuweisen',
    'You can only select %s tags' => 'Sie können nur %s Tags auswählen',
    'You can override allowed categories for this user. If empty then the predefined category for this pack will be selected' => 'Sie können zulässige Kategorien für diesen Benutzer überschreiben. Wenn leer, wird die vordefinierte Kategorie für dieses Paket ausgewählt',
    'You can process the request by going <a href="%s">here</a>' => 'Sie können die Anfrage bearbeiten, indem Sie <a href="%s">hier</a> klicken',
    'You can process the request by going here: %s' => 'Sie können die Anfrage hier bearbeiten: %s',
    'You can search vendors using Username, Shopname or Email.' => 'Sie können Anbieter mit Benutzername, Shop Name oder E-Mail suchen.',
    'You can see all registered vendors of your marketplace with their details and status.' => 'Sie können alle registrierten Anbieter Ihres Marktplatzes mit ihren Details und ihrem Status anzeigen.',
    'You can see it by going here :' => 'Sie können es sehen, indem Sie hier her gehen :',
    'You can set up two step authentication for email addresses used in account creation.' => 'Sie können eine zweistufige Authentifizierung für die bei der Account Erstellung verwendeten E-Mail Adressen einrichten.',
    'You can successfully connect Facebook with your website.' => 'Sie können Facebook erfolgreich mit Ihrer Webseite verbinden.',
