    'You can successfully connect to your Google account with your website.' => 'Sie können erfolgreich eine Verbindung zu Ihrem Google Account mit Ihrer Webseite herstellen.',
    'You can successfully connect to your Twilio account and log in from here.' => 'Sie können von hier aus erfolgreich eine Verbindung zu Ihrem Twilio Account herstellen und sich anmelden.',
