    'You can successfully connect Twitter with your website.' => 'Sie können Twitter erfolgreich mit Ihrer Webseite verbinden.',
    'You can successfully connect your Apple account with your website.' => 'Sie können Ihr Apple Account erfolgreich mit Ihrer Webseite verbinden.',
    'You can toggle vendor status simply by making them active or inactive from here.' => 'Sie können den Anbieter Status einfach umschalten, indem Sie ihn von hier aus aktivieren oder deaktivieren.',
    'You can view and edit this booking in the dashboard here: %s' => 'Sie können diese Buchung im Dashboard hier anzeigen und bearbeiten: %s',
    'You can view the order details by clicking %1$shere%2$s%3$s' => 'Sie können die Bestelldetails einsehen, indem Sie %1$shier%2$s%3$s klicken',
    'You can view the order details by clicking <a href="%1$s">here</a>%2$s' => 'Sie können die Einzelheiten der Bestellung einsehen, indem Sie <a href="%1$s">hier</a> klicken %2$s',
    'You can view the order details by clicking <a href="%s">here</a>' => 'Sie können die Bestelldetails anzeigen, indem Sie <a href="%s">hier</a> klicken',
    'You can view the order details by visiting this link. %1$s %2$s' => 'Sie können die Einzelheiten der Bestellung unter diesem Link einsehen. %1$s %2$s',
    'You can\'t sell or upload product anymore. To activate your account please contact with the admin.' => 'Sie können kein Produkt mehr verkaufen oder hochladen. Um Ihren Account zu aktivieren, wenden Sie sich bitte an den Administrator.',
    'You can\'t sell or upload product. To activate your account please contact with the admin.' => 'Sie können kein Produkt verkaufen oder hochladen. Um Ihren Account zu aktivieren, wenden Sie sich bitte an den Administrator.',
    'You cannot add another "%s" to your quote.' => 'Sie können Ihrem Angebot kein weiteres "%s" hinzufügen.',
    'You cannot add multiple vendor\'s product to your quote.' => 'Sie können Ihrem Angebot nicht das Produkt mehrerer Anbieter hinzufügen.',
    'You cannot add that amount of "%1$s"; to the cart because there is not enough stock (%2$s remaining).' => 'Sie können diese Menge von "%1$s"; nicht in den Warenkorb legen, da nicht genügend Bestand (%2$s) vorhanden ist.',
    'You do not have necessary permission.' => 'Sie verfügen nicht über die erforderliche Berechtigung.',
    'You do not have permission to create new shipping tracking because this order is not yours.' => 'Sie sind nicht berechtigt, eine neue Sendungsverfolgung zu erstellen, da dies nicht Ihre Bestellung ist.',
    'You do not have permission to create product category.' => 'Sie haben nicht die Berechtigung, eine Produkt Kategorie zu erstellen.',
    'You do not have permission to delete badges.' => 'Sie sind nicht berechtigt, Abzeichen zu löschen.',
