    'You do not have permission to perform this action.' => 'Sie haben nicht die Erlaubnis, diese Aktion durchzuführen.',
    'You do not have permission to update shipping tracking because this order is not yours.' => 'Sie sind nicht berechtigt, die Sendungsverfolgung zu aktualisieren, da dies nicht Ihre Bestellung ist.',
    'You do not have permission to use this action.' => 'Sie haben nicht die Erlaubnis, diese Aktion zu nutzen.',
    'You do not have sufficient permissions to access this page.' => 'Sie sind nicht befugt, auf diese Seite zuzugreifen.',
    'You don\'t have enough permission' => 'Sie haben nicht genug Erlaubnis',
    'You don\'t have permission to add this product.' => 'Sie sind nicht berechtigt, dieses Produkt hinzuzufügen.',
    'You don\'t have the permission.' => 'Sie haben nicht die Erlaubnis dazu.',
    'You dont have permission to perform current action.' => 'Sie sind nicht berechtigt, die aktuelle Aktion auszuführen.',
    'You have a lifetime package.' => 'Sie haben ein Paket mit unbegrenzter Laufzeit.',
    'You have a reverse withdrawal balance of %1$s to be paid. Please <a href="%2$s">pay</a> it before %3$s.' => 'Sie haben ein Auszahlungsguthaben von %1$s zu zahlen. Bitte vor dem %3$s <a href="%2$s">bezahlen</a>.',
    'You have already a processing refund request for this order.' => 'Sie haben bereits eine Rückerstattung Anfrage für diese Bestellung.',
    'You have already cloned this product.' => 'Sie haben dieses Produkt bereits geklont.',
    'You have got a new abuse report for the product' => 'Sie haben eine neue Missbrauchsmeldung für das Produkt',
