    'You have no permission to do that' => 'Sie haben keine Berechtigung, dies zu tun',
    'You have no permission to do this action' => 'Sie haben keine Berechtigung, für diese Aktion',
    'You have no permission to do this action.' => 'Sie haben keine Berechtigung zum Ausführen dieser Aktion.',
    'You have no permission to edit this coupon' => 'Sie haben keine Berechtigung, diesen Gutschein zu ändern',
    'You have no permission to manage this order' => 'Sie haben keine Berechtigung diese Bestellung zu verändern',
