    'You have not registered a card yet. You can add one below.' => 'Sie haben noch keine Karte registriert. Sie können unten eine hinzufügen.',
    'You have received an order from %s.' => 'Sie haben eine Bestellung von %s erhalten.',
    'You have successfully completed all the compliance checks.' => 'Sie haben alle Konformitätsprüfungen erfolgreich abgeschlossen.',
    'You have taken too long. Please go back and retry.' => 'Es hat zu lange gedauert. Bitte gehen Sie zurück und versuchen Sie es erneut.',
    'You have unlocked ' => 'Sie haben freigeschaltet ',
    'You just need to %1$sconfigure%2$s the %3$s plugin to make it functional.' => 'Sie müssen nur das Plugin %3$s %1$skonfigurieren%2$s, damit es funktioniert.',
    'You just need to activate the %s plugin to make it functional.' => 'Sie müssen nur das %s Plugin aktivieren, damit es funktioniert.',
    'You just need to activate the <strong>%s</strong> to make it functional.' => 'Sie müssen nur noch das <strong>%s</strong> aktivieren, um los legen zu können.',
    'You just need to install the %s plugin to make it functional.' => 'Sie müssen nur das %s Plugin installieren, damit es funktioniert.',
    'You just need to install the %sCore Plugin%s to make it functional.' => 'Sie müssen nur das %sCore Plugin%s installieren, damit es funktioniert.',
    'You just need to update the %1$s plugin to the version %2$s or later to make it functional.' => 'Sie müssen lediglich das Plugin %1$s auf die Version %2$s oder höher aktualisieren, damit es funktioniert.',
    'You might not have completed the onboarding process or %s may take some time to verify your account. Click on the "Complete Onboarding" button once again to finish the verification process.' => 'Möglicherweise haben Sie den Onboarding Prozess nicht abgeschlossen oder %s benötigt einige Zeit, um Ihr Account zu verifizieren. Klicken Sie erneut auf den "Onboarding abschließen" Button, um den Verifizierungsprozess abzuschließen.',
    'You must add the following webhook endpoint %1$s%2$s%3$s%4$s%5$s to your %6$sStripe account settings%7$s (if there isn\'t one already enabled). This will enable you to receive notifications on the charge statuses. The webhook endpoint will be attempted to be configured automatically on saving these admin settings. If it is not configured automatically, please register it manually.%8$s%9$s%10$s%11$s%12$s' => 'Sie müssen den folgenden Webhook Endpunkt %1$s%2$s%3$s%4$s%5$s zu Ihren %6$sStripe Account Einstellungen%7$s hinzufügen (falls noch keiner aktiviert ist). Dadurch können Sie Benachrichtigungen über den Ladestatus erhalten. Beim Speichern dieser Administratoreinstellungen wird versucht, den Webhook Endpunkt automatisch zu konfigurieren. Wenn es nicht automatisch konfiguriert wird, registrieren Sie es bitte manuell.%8$s%9$s%10$s%11$s%12$s',
    'You must be <a href="%s">logged in</a> to post a comment.' => 'Sie müssen <a href="%s">angemeldet</a> sein, um einen Kommentar abgeben zu können.',
    'You must provide a name.' => 'Sie müssen einen Namen angeben.',
    'You must provide customers information.' => 'Sie müssen Kundeninformationen bereitstellen.',
    'You must provide store information.' => 'Sie müssen Store Informationen angeben.',
    'You must select at least one role.' => 'Sie müssen mindestens eine Rolle auswählen.',
    'You must upload the following documents to complete the compliance checks.' => 'Sie müssen die folgenden Dokumente hochladen, um die Konformitätsprüfung abzuschließen.',
    'You need to be logged in to buy a recurring subscription pack. Please log in or create an account to proceed to the checkout.' => 'Sie müssen eingeloggt sein, um ein wiederkehrendes Abonnementpaket zu kaufen. Bitte melden Sie sich an oder erstellen Sie ein Account, um zur Kasse zu gehen.',
    'You need to enter a positive integer for this field. Enter -1 for no limit.' => 'Sie müssen eine positive ganze Zahl in dieses Feld eingeben. Geben Sie -1 für kein Limit ein.',
    'You will be able to resume anytime.' => 'Sie können jederzeit weitermachen.',
    'You will be charged in every %d' => 'Sie werden in %d belastet',
    'You will need to manually issue a refund through your payment gateway after using this.' => 'Nachdem Sie dies verwendet haben, müssen Sie manuell eine Rückerstattung über Ihr Zahlungsgateway ausstellen.',
    'You\'ll get a response to your question from the marketplace staff.' => 'Sie erhalten von den Mitarbeitern des Marktplatzes eine Antwort auf Ihre Frage.',
    'Your %1$s verification request has been %2$s by the admin.' => 'Ihre %1$s Verifizierungsanfrage wurde vom Administrator %2$s beantwortet.',
    'Your account is connected with %1$s.%2$sMerchant ID: %3$s.%4$sYou can visit your %5$s dashboard to track your payments and transactions.' => 'Ihr Account ist verbunden mit %1$s.%2$sMerchant ID: %3$s.%4$sSie können Ihr %5$s Dashboard besuchen, um Ihre Zahlungen und Transaktionen zu verfolgen.',
    'Your account is connected with MangoPay.' => 'Ihr Account ist mit MangoPay verbunden.',
    'Your account is connected with PayPal Marketplace. You can disconnect your account using the above button.' => 'Ihr Account ist mit PayPal Marketplace verbunden. Sie können die Verbindung zu Ihrem Account über den obigen Button trennen.',
    'Your account is connected with Razorpay. You can disconnect your account using the above button.' => 'Ihr Account ist mit RazorPay verbunden. Sie können Ihren Account über den obigen Button wieder trennen.',
    'Your account is connected with Stripe. You can disconnect your account using the above button.' => 'Ihr Account ist mit Stripe verbunden. Sie können Ihr Account mit dem obigen Button trennen.',
    'Your account is connected with Wirecard.' => 'Ihr Account ist mit Wirecard verbunden.',
    'Your Account is not connected to Stripe Express' => 'Ihr Account ist nicht mit Stripe Express verbunden',
    'Your account is not connected to Wirecard. Connect your Wirecard account to receive payouts.' => 'Ihr Account ist nicht mit Wirecard verbunden. Verbinden Sie Ihren Wirecard Account, um Auszahlungen zu erhalten.',
    'Your account is not connected with %s. Click on the button below to sign up.' => 'Ihr Account ist nicht mit %s verbunden. Klicken Sie auf den Button unten, um sich anzumelden.',
    'Your account is not connected with MangoPay. Connect your %1$s MangoPay%2$s account to receive automatic payouts.' => 'Ihr Account ist nicht mit MangoPay verbunden. Verbinden Sie Ihr %1$s MangoPay%2$s Account, um automatische Auszahlungen zu erhalten.',
    'Your account is not connected with MangoPay. Update the informations below to complete signing up.' => 'Ihr Account ist nicht mit MangoPay verbunden. Aktualisieren Sie die Informationen unten, um die Anmeldung abzuschließen.',
    'Your account is not connected with PayPal Marketplace. Connect your %1$s PayPal%2$s account to receive automatic payouts.' => 'Ihr Account ist nicht mit PayPal Marketplace verbunden. Verbinden Sie Ihr %1$s PayPal%2$s Account, um automatische Auszahlungen zu erhalten.',
    'Your account is not connected with Razorpay. Connect your %1$s Razorpay%2$s account to receive automatic payouts.' => 'Ihr Account ist nicht mit RazorPay verbunden. Verbinden Sie Ihren %1$s RazorPay%2$s Account, um automatische Auszahlungen zu erhalten.',
    'Your account is not connected with Razorpay. Please click Sign Up button to connect your Razorpay account.' => 'Ihr Account ist nicht mit RazorPay verbunden. Bitte klicken Sie auf den Anmelden Button, um Ihr Razorpay Account zu verbinden.',
    'Your account is not connected with Stripe. Connect your Stripe account to receive automatic payouts.' => 'Ihr Account ist nicht mit Stripe verbunden. Verbinden Sie Ihren Stripe Account, um automatische Auszahlungen zu erhalten.',
    'Your account is not connected with Stripe. Connect your Stripe account to receive payouts.' => 'Ihr Account ist nicht mit Stripe verbunden. Verbinden Sie Ihren Stripe Account, um Auszahlungen zu erhalten.',
    'Your account is not eligible for Payout yet. Please make sure you have verified all the required KYC documents.' => 'Ihr Account ist noch nicht für eine Auszahlung berechtigt. Bitte stellen Sie sicher, dass Sie alle erforderlichen KYC Dokumente überprüft haben.',
    'Your API credentials are a API Key and secret, which authenticate API requests from your account. You get these credentials from a REST API app in the Developer Dashboard. Visit <a href="%s">this link</a> for more information about getting your api details.' => 'Ihre API Anmeldeinformationen sind ein API Key und ein Secret, die API Anforderungen von Ihrem Account authentifizieren. Sie erhalten diese Anmeldeinformationen von einer REST API App im Entwickler Dashboard. Besuchen Sie <a href="%s">diesen Link</a>, um weitere Informationen zum Abrufen Ihrer API Details zu erhalten.',
    'Your API credentials are a client ID and API key, which authenticate API requests from your account. You can collect these credentials from a REST API app in the Developer Dashboard. Visit %s for more information about getting your api details.' => 'Ihre API Anmeldeinformationen sind eine Client ID und ein API Key, mit denen API Anforderungen von Ihrem Account aus authentifiziert werden. Sie können diese Anmeldeinformationen von einer REST API Anwendung im Developer Dashboard abrufen. Besuchen Sie %s für weitere Informationen zum Abrufen Ihrer API Details.',
    'Your API credentials are a client ID and secret, which authenticate API requests from your account. You get these credentials from a REST API app in the Developer Dashboard. Visit <a href="%1$s">this link</a> for more information about getting your api details.' => 'Ihre API Anmeldeinformationen sind eine Client ID und ein Secret, mit denen API Anforderungen von Ihrem Account aus authentifiziert werden. Sie erhalten diese Anmeldeinformationen von einer REST API App im Developer Dashboard. Besuchen Sie <a href="%1$s">diesen Link</a> für weitere Informationen zum Abrufen Ihrer API Details.',
    'Your API credentials are a publishable key and a secret key, which authenticate API requests from your account. You can collect these credentials from a REST API app in the Developer Dashboard. Visit %1$sthis link%2$s for more information about getting your api details.%3$s%4$sNote: Even if you enable test mode, please provide your live API keys as well. For some extra configurations for payment methods like Apple Pay and payment request buttons, live API keys are required even in test mode.%5$s' => 'Ihre API Anmeldeinformationen sind ein Publishable Key und ein Secret Key, die API Anforderungen von Ihrem Account authentifizieren. Sie können diese Anmeldeinformationen von einer REST API App im Entwickler Dashboard erfassen. Unter %1$sdiesem Link%2$s finden Sie weitere Informationen zum Abrufen Ihrer API Details.%3$s%4$sHinweis: Auch wenn Sie den Testmodus aktivieren, geben Sie bitte auch Ihre Live API Schlüssel an. Für einige zusätzliche Konfigurationen für Zahlungsmethoden wie Apple Pay und Zahlungsanforderung Buttons sind auch im Testmodus Live API Keys erforderlich.%5$s',
    'Your card could not be set up for future usage.' => 'Ihre Karte konnte nicht für die zukünftige Verwendung eingerichtet werden.',
