    'Your data is safe, renew anytime to unlock PRO features. After renewal, your marketplace will seamlessly resume.' => 'Ihre Daten sind sicher. Sie können jederzeit erneuern, um PRO Funktionen freizuschalten. Nach der Erneuerung wird Ihr Marktplatz nahtlos fortgesetzt.',
